"""A least-recently-used cache with optional entry expiration."""
import time
from collections import OrderedDict
from dataclasses import dataclass


USE_DEFAULT = object()


def _validate_ttl(ttl):
    if ttl is not None:
        try:
            if ttl > 0:
                return
        except TypeError:
            pass
        raise ValueError("ttl must be greater than zero")


@dataclass
class _Entry:
    value: object
    stored_at: float
    ttl: object

    def expired(self, now):
        return self.ttl is not None and now - self.stored_at >= self.ttl


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        _validate_ttl(ttl)
        self.capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._items = OrderedDict()

    def _live_entry(self, key):
        entry = self._items.get(key)
        if entry is not None and entry.expired(self._clock()):
            del self._items[key]
            return None
        return entry

    def _purge_expired(self, now):
        expired = [key for key, entry in self._items.items() if entry.expired(now)]
        for key in expired:
            del self._items[key]

    def get(self, key, default=None):
        """Return the value and mark the entry as most recently used."""
        entry = self._live_entry(key)
        if entry is None:
            return default
        self._items.move_to_end(key)
        return entry.value

    def peek(self, key, default=None):
        """Return the value without touching the order."""
        entry = self._live_entry(key)
        return default if entry is None else entry.value

    def put(self, key, value, ttl=USE_DEFAULT):
        if ttl is USE_DEFAULT:
            ttl = self._ttl
        _validate_ttl(ttl)
        now = self._clock()
        if key not in self._items and len(self._items) >= self.capacity:
            self._purge_expired(now)
            if len(self._items) >= self.capacity:
                self._items.popitem(last=False)
        self._items[key] = _Entry(value, now, ttl)
        self._items.move_to_end(key)

    def keys(self):
        """Live keys from least to most recently used."""
        self._purge_expired(self._clock())
        return list(self._items)

    def __contains__(self, key):
        return self._live_entry(key) is not None

    def __len__(self):
        self._purge_expired(self._clock())
        return len(self._items)
